// Tests for src/sidebar-groups.mjs: the autogenerated `cli` directory group under
// "Using Brahma" is shown as a collapsed "CLI reference" group.
//
// Run: npm test (node --test).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { relabelGroups, GROUP_LABELS } from '../src/sidebar-groups.mjs';

const link = (href, label, isCurrent = false) => ({ type: 'link', label, href, isCurrent, badge: undefined, attrs: {} });
const group = (label, entries) => ({ type: 'group', label, entries, collapsed: false, badge: undefined });

function sidebar() {
  return [
    group('Using Brahma', [
      link('/docs/', 'Using Brahma'),
      group('concepts', [link('/docs/concepts/companies/', 'Companies')]),
      group('cli', [
        link('/docs/cli/', 'Overview'),
        group('company', [link('/docs/cli/company/', 'Overview'), link('/docs/cli/company/create/', 'create', true)]),
        link('/docs/cli/log/', 'log'),
      ]),
    ]),
    group('Inside Brahma', [group('cli', [link('/internals/cli/', 'Not the reference')])]),
  ];
}

test('the docs/cli group is relabelled "CLI reference" and collapsed, nested groups too', () => {
  const s = sidebar();
  relabelGroups(s, GROUP_LABELS);
  const cli = s[0].entries[2];
  assert.equal(cli.label, 'CLI reference');
  assert.equal(cli.collapsed, true);
  assert.equal(cli.entries[1].label, 'company', 'nested group labels are kept');
  assert.equal(cli.entries[1].collapsed, true);
  assert.equal(cli.entries[1].entries[1].isCurrent, true, 'current entry untouched');
});

test('other groups are left alone, including a "cli" group outside /docs/cli/', () => {
  const s = sidebar();
  relabelGroups(s, GROUP_LABELS);
  assert.equal(s[0].label, 'Using Brahma');
  assert.equal(s[0].collapsed, false);
  assert.equal(s[0].entries[1].label, 'concepts');
  assert.equal(s[0].entries[1].collapsed, false);
  assert.equal(s[1].entries[0].label, 'cli');
  assert.equal(s[1].entries[0].collapsed, false);
});

test('a sidebar without the generated reference is unchanged', () => {
  const s = [group('Using Brahma', [link('/docs/', 'Using Brahma')])];
  const before = structuredClone(s);
  relabelGroups(s, GROUP_LABELS);
  assert.deepEqual(s, before);
});
